mapper.update:
UPDATE candidate_job_match_analyses
SET status = 'PENDING',
    deadline_at = NULL,
    failure_reason = #{failureReason},
    trace_id = #{traceId},
    updated_at = #{now}
WHERE id = #{analysisId}
  AND attempt_count = #{attemptCount}
  AND status = 'PROCESSING'

UPDATE candidate_job_match_analyses
SET status = 'FAILED',
    deadline_at = NULL,
    failure_reason = #{failureReason},
    trace_id = #{traceId},
    updated_at = #{now}
WHERE id = #{analysisId}
  AND attempt_count = #{attemptCount}
  AND status = 'PROCESSING'

UPDATE candidate_job_match_analyses
SET status = 'FAILED',
    deadline_at = NULL,
    failure_reason = #{failureReason},
    trace_id = #{traceId},
    updated_at = #{now}
WHERE id = #{analysisId}
  AND attempt_count >= #{maxAttempts}
  AND (
      status = 'PENDING'
      OR (
          status = 'PROCESSING'
          AND (deadline_at IS NULL OR deadline_at <= #{now})
      )
  )
